-- Repaired form-template seed: 20260710054400_reseed_people_it_form_templates.
-- The original 2026-01 seed contained malformed JSON delimiters and is now a
-- safe historical marker. This idempotent seed preserves the intended forms.

with seed as (
  select
    (item->>'module')::public.module_type as module,
    item->>'name' as name,
    item->>'description' as description,
    item->'schema_json' as schema_json,
    coalesce((item->>'is_active')::boolean, true) as is_active
  from jsonb_array_elements($hpg_forms$[{"module":"hr","name":"Attendance Form","description":"Submit attendance or time tracking information","schema_json":{"fields":[{"name":"employee_name","type":"text","label":"Employee Name","required":true},{"name":"period_start","type":"date","label":"Period Start","required":true},{"name":"period_end","type":"date","label":"Period End","required":true},{"name":"hours_worked","type":"number","label":"Hours Worked"},{"name":"leave_taken","type":"select","label":"Leave Taken","options":["None","Sick Leave","Vacation","Personal","Other"]},{"name":"notes","type":"textarea","label":"Notes"}]},"is_active":true},{"module":"hr","name":"Interview scorecard","description":"Record interview feedback and scoring","schema_json":{"fields":[{"name":"candidate_name","type":"text","label":"Candidate Name","required":true},{"name":"position","type":"text","label":"Position","required":true},{"name":"interview_date","type":"date","label":"Interview Date","required":true},{"name":"overall_score","type":"select","label":"Overall Score","options":["1 - Poor","2 - Fair","3 - Good","4 - Very Good","5 - Excellent"],"required":true},{"name":"strengths","type":"textarea","label":"Strengths","required":true},{"name":"concerns","type":"textarea","label":"Concerns"},{"name":"recommendation","type":"select","label":"Recommendation","options":["Strong Hire","Hire","Maybe","Do Not Hire"],"required":true}]},"is_active":true},{"module":"hr","name":"Offer approval","description":"Request approval for job offer","schema_json":{"fields":[{"name":"candidate_name","type":"text","label":"Candidate Name","required":true},{"name":"position","type":"text","label":"Position","required":true},{"name":"proposed_salary","type":"number","label":"Proposed Salary ($)","required":true},{"name":"start_date","type":"date","label":"Proposed Start Date","required":true},{"name":"justification","type":"textarea","label":"Justification","required":true},{"name":"approval_level","type":"select","label":"Approval Level Required","options":["Department Head","VP","CEO"]}]},"is_active":true},{"module":"hr","name":"Staffing Request","description":"Request new staff position or replacement","schema_json":{"fields":[{"name":"position_title","type":"text","label":"Position Title","required":true},{"name":"department","type":"text","label":"Department","required":true},{"name":"request_type","type":"select","label":"Request Type","options":["New Position","Replacement","Temporary"],"required":true},{"name":"justification","type":"textarea","label":"Justification","required":true},{"name":"budget_impact","type":"number","label":"Budget Impact ($)"},{"name":"urgency","type":"select","label":"Urgency","options":["Low","Medium","High"],"required":true}]},"is_active":true},{"module":"it","name":"Access request","description":"Request access to tools, systems, or accounts","schema_json":{"fields":[{"name":"user_name","type":"text","label":"User Full Name","required":true},{"name":"user_email","type":"email","label":"User Email","required":true},{"name":"systems","type":"multiselect","label":"Systems Needed","options":["Google Workspace","Slack","Trello","HPG Workstation","Drive Access","Supabase","Other"],"required":true},{"name":"role","type":"select","label":"Role/Permission Level","options":["Staff","Manager","Admin"]},{"name":"start_date","type":"date","label":"Start Date"},{"name":"justification","type":"textarea","label":"Justification"}]},"is_active":true},{"module":"it","name":"Support ticket","description":"Submit IT support request or report an issue","schema_json":{"fields":[{"name":"issue_type","type":"select","label":"Issue Type","options":["Hardware","Software","Network","Account Access","Other"],"required":true},{"name":"description","type":"textarea","label":"Description","required":true},{"name":"severity","type":"select","label":"Severity","options":["Low","Medium","High","Critical"],"required":true},{"name":"affected_users","type":"text","label":"Affected Users"},{"name":"steps_to_reproduce","type":"textarea","label":"Steps to Reproduce"}]},"is_active":true}]$hpg_forms$::jsonb) as seeded(item)
)
insert into public.form_templates (module, name, description, schema_json, is_active)
select module, name, description, schema_json, is_active
from seed
on conflict (module, name) do update set
  description = excluded.description,
  schema_json = excluded.schema_json,
  is_active = excluded.is_active,
  updated_at = now();
